DataSciencePapers |&gt;
  group_by(primary_category) |&gt;
  count()


DataSciencePapers &lt;- DataSciencePapers |&gt;
  mutate(field = str_extract(primary_category, pattern = "^[a-z,-]+"))

mosaic::tally(x = ~field, margins = TRUE, data = DataSciencePapers) |&gt;
